#include <vector>
#define main hecbench_original_main
#include "atan2-cuda/main.cu"
#undef main
void emit(int trial,double seconds,const std::vector<double>&result,const std::vector<double>&expected,int repeat,double atol=0.,double rtol=0.){
 double error=0;bool correct=result.size()==expected.size();for(size_t i=0;i<result.size();i++){double e=fabs(result[i]-expected[i]);error=fmax(error,e);correct &= std::isfinite(result[i])&&e<=atol+rtol*fabs(expected[i]);}char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(result.data(),8,result.size(),f);fclose(f);
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"timing_region\":\"synchronized_kernel_loop_mean\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,correct?"true":"false",result.size(),error,repeat,path,result.size());if(!correct)exit(1);
}
int main(int argc,char**argv){int n=argc>1?atoi(argv[1]):4096,repeat=argc>2?atoi(argv[2]):10;std::vector<float>x(n),y(n),rf(n),of(n);std::vector<int>ri(n),oi(n);std::vector<short>rs(n),os(n);for(int i=0;i<n;i++){x[i]=4.f+float(i%1024)/256.f;y[i]=.25f+float((i*37)%1024)/1024.f;}reference_f(n,x.data(),y.data(),rf.data());reference_i(n,x.data(),y.data(),ri.data());reference_s(n,x.data(),y.data(),rs.data());std::vector<double>expected;for(auto v:rf)expected.push_back(v);for(auto v:ri)expected.push_back(v);for(auto v:rs)expected.push_back(v);float *dx,*dy,*df;int*di;short*ds;cudaMalloc(&dx,n*4);cudaMalloc(&dy,n*4);cudaMalloc(&df,n*4);cudaMalloc(&di,n*4);cudaMalloc(&ds,n*2);cudaMemcpy(dx,x.data(),n*4,cudaMemcpyHostToDevice);cudaMemcpy(dy,y.data(),n*4,cudaMemcpyHostToDevice);auto launch=[&](int c){if(c==1)compute_f<<<(n+255)/256,256>>>(n,dx,dy,df);else if(c==2)compute_i<<<(n+255)/256,256>>>(n,dx,dy,di);else compute_s<<<(n+255)/256,256>>>(n,dx,dy,ds);};for(int c=1;c<=3;c++)launch(c);cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){double total=0;std::vector<double>values;for(int c=1;c<=3;c++){cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int j=0;j<repeat;j++)launch(c);cudaDeviceSynchronize();total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;if(c==1){cudaMemcpy(of.data(),df,n*4,cudaMemcpyDeviceToHost);for(auto v:of)values.push_back(v);}else if(c==2){cudaMemcpy(oi.data(),di,n*4,cudaMemcpyDeviceToHost);for(auto v:oi)values.push_back(v);}else{cudaMemcpy(os.data(),ds,n*2,cudaMemcpyDeviceToHost);for(auto v:os)values.push_back(v);}}emit(trial,total,values,expected,repeat,1e-6);}cudaFree(dx);cudaFree(dy);cudaFree(df);cudaFree(di);cudaFree(ds);return 0;}
